// A small diffuse lightmap for the recessed neon panels along the raceway.
// Sample on the back wall of a real cavity. The open front faces the canal.
struct NeonCavity {
    static constexpr int cols=16,rows=12;
    C tex[rows][cols];
    struct Hit { V point,normal; int wall; };
    static Hit hit(V p,V d){
        double nearest=1e9; Hit h{};
        auto wall=[&](double distance,V n,int face){
            if(distance>.0001 && distance<nearest){nearest=distance;h={p+d*distance,n,face};}
        };
        if(d.x>0)wall((3-p.x)/d.x,{-1,0,0},1);
        if(d.x<0)wall((-3-p.x)/d.x,{1,0,0},0);
        if(d.y>0)wall((4-p.y)/d.y,{0,-1,0},3);
        if(d.y<0)wall(-p.y/d.y,{0,1,0},2);
        if(d.z>0)wall((2-p.z)/d.z,{0,0,-1},5);
        if(d.z<0)wall(-p.z/d.z,{0,0,1},4);
        return h;
    }
    static V radiance(V p,V d,int depth,int seed){
        auto h=hit(p,d);
        if(h.wall==4)return {.075,.095,.14};
        if(h.wall==3 && std::abs(h.point.x)>1.55 && h.point.z>.3)
            return h.point.x<0?V{.12,3.8,5.2}:V{5.1,.48,1.5};
        if(depth==0)return {.035,.03,.052};
        double r=std::sqrt(random01(seed+2)),a=2*pi*random01(seed+6);
        V side=h.normal.x!=0?V{0,1,0}:V{1,0,0};
        V tangent={h.normal.y*side.z-h.normal.z*side.y,h.normal.z*side.x-h.normal.x*side.z,h.normal.x*side.y-h.normal.y*side.x};
        V ray=side*(r*std::cos(a))+tangent*(r*std::sin(a))+h.normal*std::sqrt(1-r*r);
        return radiance(h.point+h.normal*.001,ray,depth-1,seed+891)*.72;
    }
    NeonCavity(){
        for(int y=0;y<rows;y++)for(int x=0;x<cols;x++){
            V sum{}; V start={-3+6*(x+.5)/cols,4*(y+.5)/rows,1.998};
            for(int i=0;i<768;i++){
                int seed=(y*cols+x)*3001+i*37;
                double r=std::sqrt(random01(seed)),a=2*pi*random01(seed+1);
                sum=sum+radiance(start,{r*std::cos(a),r*std::sin(a),-std::sqrt(1-r*r)},2,seed);
            }
            auto expose=[](double value){return int(255*std::sqrt(1-std::exp(-value/768*1.65)));};
            tex[y][x]={expose(sum.x),expose(sum.y),expose(sum.z)};
        }
    }
};

demko/race.hpp:
#pragma once
#include <algorithm>
#include <array>
#include <cmath>
#include <vector>
#include "junction.hpp"

namespace neon {
inline double bound(double x, double a, double b) { return std::clamp(x, a, b); }
inline double road(double z) {
    double a = tau * z / lapLength;
    return 17 * sin(3 * a) + 10 * sin(2 * a + .8) + 4 * sin(6 * a - .6) + chicane(z);
}
inline double slope(double z) {
    double a = tau * z / lapLength;
    return tau / lapLength * (51 * cos(3 * a) + 20 * cos(2 * a + .8) + 24 * cos(6 * a - .6)) +
           (chicane(z + .1) - chicane(z - .1)) / .2;
}
inline double gap(double a, double b) {
    double d = a - b;
    return d - lapLength * floor(d / lapLength + .5);
}
struct Input {
    int steer = 0;
    bool boost = false, brake = false;
};
enum class Cue { Fire, Rocket, Break, Hit, Pad, Rail, Repair, Lap, Launch };
struct Sector {
    double x, z, mineX;
    bool mine, used = false;
};
inline Sector sector(int i) {
    constexpr int lanes[] = {0, 10, 15, 5, -8, -14, -4, 9, 13, 0, -12, -6};
    double x = lanes[i % 12];
    double z = 56. + i * 96;
    if (islandHalf(z) > 0)
        x = routeSign(x) * std::max(std::abs(x), islandHalf(z) + 3.5);
    double mine = x + (x > 0 ? -7 : 7);
    return {x, z, mine, i % 3 != 0 && (islandHalf(z - 17) == 0 || std::abs(mine) > islandHalf(z - 17) + 2)};
}
struct Pilot {
    double x, z, speed, lean = 0, stun = 0, boost = 0, hitGlow = 0;
};
struct Shot {
    double x, z;
    bool rocket, spent = false;
    int target = -1;
};
struct Burst {
    double x, z, age = 0;
};
using Object = std::array<float, 4>;

struct Race {
    double distance = 0, elapsed = 0, x = 0, vx = 0, lean = 0, speed = 36, thrust = 0, energy = 100;
    double cooldown = 0, rocketCooldown = 0, immunity = 0, padBoost = 0, wallLock = 0, lapStart = 0,
           lastLap = 0;
    int laps = 0, shield = 3, rockets = 2, rank = 7, refills = 0, nextSector = 3;
    bool drafting = false, spent = false;
    double wakeCharge = 0, launchTime = 0, chargedLane = 0, steerMemory = 0;
    int wakePilot = -1, forkSide = 0;
    std::array<Pilot, 6> rivals{};
    std::vector<Sector> sectors = {sector(0), sector(1), sector(2)};
    std::vector<Shot> shots;
    std::vector<Burst> bursts;
    std::vector<Cue> cues;
    Race() {
        constexpr double lanes[] = {0, 6, -12, 12, -3, 3};
        constexpr double grid[] = {9, 9, 19, 19, 53, 77};
        for (int i = 0; i < 6; i++)
            rivals[i] = {lanes[i], grid[i], 37. + i * .8};
    }
    int targetAhead() const {
        int id = -1;
        double best = 75;
        for (int i = 0; i < int(rivals.size()); ++i) {
            const auto &p = rivals[i];
            double dz = gap(p.z, distance), lateral = std::abs(p.x - x);
            if (islandHalf(distance) > 0 && islandHalf(p.z) > 0 && routeSign(x) != routeSign(p.x))
                continue;
            if (dz < 3 || dz > 64 || lateral > 2.8 + .12 * dz)
                continue;
            const double score = dz + 2 * lateral;
            if (score < best) {
                best = score;
                id = i;
            }
        }
        return id;
    }
    void shoot(bool rocket) {
        if (rocket) {
            if (!rockets || rocketCooldown > 0)
                return;
            rockets--;
            rocketCooldown = .65;
        } else {
            if (cooldown > 0)
                return;
            cooldown = .20;
        }
        shots.push_back({x, distance + 2, rocket, false, rocket ? targetAhead() : -1});
        cues.push_back(rocket ? Cue::Rocket : Cue::Fire);
    }
    void impact() {
        if (immunity > 0)
            return;
        immunity = 1.2;
        speed *= .75;
        if (--shield == 0) {
            shield = 3;
            energy = std::max(25., energy * .5);
            speed = 20;
            immunity = 2;
            cues.push_back(Cue::Repair);
        } else
            cues.push_back(Cue::Hit);
    }
    void movePilots(double dt) {
        drafting = false;
        wakePilot = -1;
        double nearestWake = 28;
        for (int i = 0; i < 6; i++) {
            auto &p = rivals[i];
            double ahead = gap(p.z, distance), phase = tau * p.z / lapLength;
            double bend = slope(p.z + 28) - slope(p.z - 4);
            int index = std::max(0, int(ceil((p.z - 56) / 96)));
            auto pad = sector(index);
            double approach = pad.z - p.z;
            double line =
                bound(8 * sin(phase * 2 + i * 1.6) + 5 * sin(phase * 5 + i) + bend * 19, -15, 15);
            if (approach < 40 && (index + i) % 3)
                line += (pad.x - line) * (1 - approach / 40);
            if (ahead < 2 && ahead > -17 && fabs(p.x - x) < 3.5)
                line = bound(x + (p.x >= x ? 5 : -5), -16, 16);
            for (auto &other : rivals) {
                if (&other == &p)
                    continue;
                double lead = gap(other.z, p.z);
                if (lead > 0 && lead < 9 && fabs(other.x - p.x) < 2.5)
                    line += p.x >= other.x ? 3 : -3;
            }
            if (i == 0 && p.z < 66)
                line *= bound((p.z - 34) / 32, 0, 1);
            double island = islandHalf(p.z);
            if (island > 0)
                line = routeSign(p.x) * std::max(island + 3., routeSign(p.x) * line);
            double dx = bound((line - p.x) * 1.5, -10, 10);
            p.x = bound(p.x + dx * dt, -16.4, 16.4);
            if (island > 0)
                p.x = routeSign(line) * std::max(island + 1.35, std::abs(p.x));
            p.lean = -dx * .035;
            p.hitGlow = std::max(0., p.hitGlow - dt);
            p.stun = std::max(0., p.stun - dt);
            double surge = pow(std::max(0., sin(phase * 4 + i * 1.9)), 6);
            double target = 46 + i * 1.1 + 8 * surge + (p.boost > 0 ? 12 : 0) - 8 * fabs(bend) +
                            bound((distance - p.z) * .19, -14, 16);
            target += 1.4 * bridgeHeight(p.x, p.z);
            p.boost = std::max(0., p.boost - dt);
            if (approach >= 0 && approach < p.speed * dt && fabs(p.x - pad.x) < 3)
                p.boost = 1.2;
            p.speed += ((p.stun > 0 ? target * .53 : target) - p.speed) * (1 - exp(-2 * dt));
            p.z += p.speed * dt;
            if ((islandHalf(distance) == 0 || routeSign(p.x) == routeSign(x)) && ahead > 2 &&
                ahead < nearestWake && fabs(p.x - x) < 3) {
                drafting = true;
                wakePilot = i;
                nearestWake = ahead;
            }
        }
    }
    void stepShots(double dt) {
        for (auto &shot : shots) {
            if (shot.target >= 0 && gap(rivals[shot.target].z, shot.z) > 0)
                shot.x += bound(rivals[shot.target].x - shot.x, -17 * dt, 17 * dt);
            double prev = shot.z;
            shot.z += dt * (shot.rocket ? 126 : 116);
            if (islandHalf(shot.z) > 0 && std::abs(shot.x) < islandHalf(shot.z)) {
                shot.spent = true;
                bursts.push_back({shot.x, shot.z});
                continue;
            }
            double best = shot.z + 2, hitX = 0;
            Pilot *pilot = nullptr;
            Sector *mine = nullptr;
            auto inPath = [&](double xx, double z) {
                return z >= prev - 1 && z <= shot.z + 1 && z < best &&
                       fabs(xx - shot.x) < (shot.rocket ? 4 : 1.55);
            };
            for (auto &p : rivals) {
                double z = prev + gap(p.z, prev);
                if (inPath(p.x, z)) {
                    best = z;
                    hitX = p.x;
                    pilot = &p;
                }
            }
            for (auto &s : sectors)
                if (s.mine && inPath(s.mineX, s.z - 17)) {
                    best = s.z - 17;
                    hitX = s.mineX;
                    mine = &s;
                    pilot = nullptr;
                }
            if (pilot || mine) {
                if (pilot) {
                    pilot->stun = shot.rocket ? 2.4 : 1;
                    pilot->hitGlow = .75;
                } else
                    mine->mine = false;
                shot.spent = true;
                bursts.push_back({hitX, best});
                cues.push_back(Cue::Break);
            }
        }
        std::erase_if(shots, [&](auto &s) { return s.spent || s.z >= distance + 143; });
        for (auto &b : bursts)
            b.age += dt;
        std::erase_if(bursts, [](auto &b) { return b.age >= .45; });
    }
    void advance(double dt, Input in) {
        elapsed += dt;
        for (double *t : {&cooldown, &rocketCooldown, &immunity, &wallLock, &padBoost})
            *t = std::max(0., *t - dt);
        movePilots(dt);
        double bend = slope(distance + 16) - slope(distance - 8);
        double target = in.steer * (in.brake ? 29 : 22) - bend * speed * (in.brake ? .28 : .75);
        vx += (target - vx) * (1 - exp(-7 * dt));
        x = bound(x + vx * dt, -18, 18);
        if (fabs(x) >= 18 && vx * x > 0 && wallLock == 0) {
            speed *= .82;
            vx *= .15;
            wallLock = .9;
            cues.push_back(Cue::Rail);
        }
        lean += (-vx * .027 - bend * .44 - lean) * (1 - exp(-8 * dt));
        launchTime = std::max(0., launchTime - dt);
        steerMemory = in.steer ? 0.5 : std::max(0., steerMemory - dt);
        if (wakeCharge >= 1 && in.boost && steerMemory > 0 && std::abs(x - chargedLane) > 1.25 &&
            !in.brake) {
            launchTime = 1.2;
            wakeCharge = 0;
            immunity = std::max(immunity, .45);
            cues.push_back(Cue::Launch);
        }
        if (drafting && !in.boost && launchTime == 0 && wakeCharge < 1) {
            wakeCharge = std::min(1., wakeCharge + dt / 1.05);
            if (wakeCharge == 1)
                chargedLane = x;
        } else if (!drafting && wakeCharge < 1)
            wakeCharge = std::max(0., wakeCharge - dt * .20);
        bool boost = in.boost && !in.brake && energy > 0 && !spent;
        if (boost && launchTime == 0) {
            energy = std::max(0., energy - 22 * dt);
            if (energy == 0)
                spent = true;
        } else {
            energy = std::min(100., energy + (drafting ? 24 : 10) * dt);
            if (!in.boost || energy > 30)
                spent = false;
        }
        thrust += ((boost || padBoost > 0 || launchTime > 0) - thrust) * (1 - exp(-6 * dt));
        speed += ((in.brake ? 29.
                            : 39 + (forkSide < 0 ? 1.4 * bridgeHeight(x, distance) : 0.) + 24 * thrust +
                                  (drafting ? 6 : 0) + (launchTime > 0 ? 20 : 0)) -
                  speed) *
                 (1 - exp(-2.4 * dt));
        double before = distance, travel = speed * dt / bound(1 - bend * x / 24, .87, 1.13);
        if (forkSide > 0)
            energy = std::min(100., energy + 18 * dt);
        distance += travel;
        const double island = islandHalf(distance);
        if (island > 0) {
            if (!forkSide)
                forkSide = routeSign(x);
            double clearance = forkSide * x - island;
            if (clearance < 1.3) {
                x = forkSide * (island + 1.3);
                if (clearance < 1.2 && wallLock == 0) {
                    speed *= .86;
                    wallLock = .8;
                    cues.push_back(Cue::Rail);
                }
                vx = forkSide * std::max(0., forkSide * vx);
            }
        } else
            forkSide = 0;
        while (nextSector * 96 < distance + 210)
            sectors.push_back(sector(nextSector++));
        std::erase_if(sectors, [&](auto &s) { return s.z <= distance - 30; });
        for (auto &s : sectors) {
            if (s.mine && before < s.z - 17 && distance >= s.z - 17) {
                s.mine = false;
                if (fabs(s.mineX - x) < 1.55)
                    impact();
            }
            if (!s.used && before < s.z && distance >= s.z) {
                s.used = true;
                if (fabs(s.x - x) < 2.9) {
                    energy = std::min(100., energy + 24);
                    padBoost = 1.05;
                    if (++refills % 2 == 0)
                        rockets = std::min(3, rockets + 1);
                    shield = std::min(3, shield + 1);
                    cues.push_back(Cue::Pad);
                }
            }
        }
        for (auto &p : rivals)
            if (fabs(gap(p.z, distance)) < 1.8 && fabs(x - p.x) < 2 && immunity == 0) {
                impact();
                p.stun = .7;
                vx += (x >= p.x ? 7 : -7);
            }
        stepShots(dt);
        rank = 1;
        for (auto &p : rivals)
            if (p.z > distance)
                rank++;
        if (int(floor(distance / lapLength)) > laps) {
            laps++;
            double at = elapsed - (distance - laps * lapLength) * dt / travel;
            lastLap = at - lapStart;
            lapStart = at;
            cues.push_back(Cue::Lap);
        }
    }
    std::vector<Object> visible() const {
        std::vector<Object> out;
        double offset = laps * lapLength;
        auto add = [&](double xx, double z, int k, double age = 0) {
            out.push_back({float(xx), float(z - offset), float(k), float(age)});
        };
        for (int i = 0; i < 6; i++) {
            auto &p = rivals[i];
            double dz = gap(p.z, distance);
            if (dz > -10 && dz < 158)
                add(p.x, distance + dz, 6 + i, p.lean);
        }
        const int locked = rockets > 0 ? targetAhead() : -1;
        for (int i = 0; i < int(rivals.size()); i++) {
            const auto &p = rivals[i];
            double dz = gap(p.z, distance);
            if (dz < 0 || dz > 100)
                continue;
            if (p.hitGlow > 0)
                add(p.x, distance + dz, 14, p.hitGlow / .75);
            else if (i == locked)
                add(p.x, distance + dz, 13);
            if (i == wakePilot)
                add(p.x, distance + dz, 12, wakeCharge);
        }
        for (auto &s : sectors) {
            if (!s.used && s.z < distance + 153)
                add(s.x, s.z, 0);
            if (s.mine && s.z - 17 < distance + 145)
                add(s.mineX, s.z - 17, 1);
        }
        for (auto &s : shots)
            add(s.x, s.z, s.rocket ? 3 : 2);
        for (auto &b : bursts)
            add(b.x, b.z, 5, b.age);
        return out;
    }
};
} // namespace neon

demko/race_fx.inc:
// Raceway lighting and the arcade encounter, in the same world coordinates as the ship.
void lightBays(){
    if(stage<6)return;
    static const NeonCavity lightmap;
    int first=int(cz/24)-(block?0:1);
    for(int k=first;k<first+(block?1:9);k++){
        double z=24*k+23;
        int side=(k%2==0)?1:-1;
        double x=side*(block?10.3:7.8)*widthFactor;
        box(x-.22,0,z,.44,7.5,.6,{59,63,88},{38,42,68});
        double start=x-side*3.4;
        box(std::min(start,x),6.85,z,3.4,.30,.63,{54,56,78},{35,36,56});
        box(std::min(start,x)+.10,6.90,z-.025,3.2,.055,.045,{134,164,167},{62,83,93});
        for(int j=0;j<4;j++)box(start+side*(.2+j*.85),6.78,z-.04,.12,.42,.73,{69,68,88},{43,43,63});
        if(stage<7)continue;
        // Back-lit recessed bay and two ceiling emitters. The black ribs break up the spill.
        box(x-3.17,0,z+1,6.34,7.03,2.5,{32,33,54},{64,65,84});
        if(simple)continue;
        int step=block?2:1;
        for(int y=0;y<NeonCavity::rows;y+=step)for(int c=0;c<NeonCavity::cols;c+=step){
            double l=x-3+c*6./NeonCavity::cols,b=2.92+y*4./NeonCavity::rows;
            double r=l+step*6./NeonCavity::cols,top=b+step*4./NeonCavity::rows;
            quad({l,b,z+.98},{r,b,z+.98},{r,top,z+.98},{l,top,z+.98},haze(lightmap.tex[y][c],z));
        }
        for(int sign:{-1,1}){
            C hot=sign<0?C{113,254,253}:C{255,99,155};
            double xx=x+sign*2.15;
            box(xx-.66,6.66,z+.74,1.32,.16,.2,hot,hot);
        }
        for(int j=0;j<5;j++){
            double xx=x-2.95+j*1.20;
            quad({xx,2.92,z+.76},{xx+.40,2.92,z+.76},{xx+1.30,5.85,z+.76},{xx+1.16,5.88,z+.76},{40,46,64});
        }
        box(x-3.14,2.76,z+.68,6.27,.22,.50,{85,83,104},{50,53,68});
        for(int j=0;j<4;j++)box(x-2.82+j*1.40,1.86,z+.85,.75,.07,.21,{147,155,165},{48,52,68});
    }
}
void atmosphere(){
    if(stage<8)return;
    // Integrate the shaft cross-section along each view ray up to the opaque surface.
    // World-space emitters stay stationary as the camera passes between them.
    int first=int(std::floor((cz-27)/24));
    for(int k=first;k<=first+5;k++){
        if(k%3!=0 && stage<14)continue;
        int side=k%2==0?1:-1;
        double fixture=24*k+23.8,rel=fixture-cz;
        double reach=1-ease((rel-64)/32);
        if(rel< -5 || reach<=0)continue;
        double bx=cx-bend(fixture)-side*(7.8*widthFactor-1.26*(6.82-cy));
        double bz=-rel-.29*(6.82-cy);
        for(int y=0;y<H;y+=2)for(int x=0;x<W;x+=2){
            double sx=(x-W*.5)/focus,sy=(H*.43-y)/focus;
            double dy=(sy+roll*sx)/(1+roll*roll),dx=(sx-roll*sy)/(1+roll*roll)-side*1.26*dy;
            double dz=1+.29*dy;
            double aa=dx*dx+.43*dz*dz;
            double mid=-(bx*dx+.43*bz*dz)/aa;
            double drop=6.82-cy-mid*dy;
            double radius=.84+.68*reveal(13,.22)+.20*std::clamp(drop,0.,6.82);
            double ex=bx+dx*mid,ez=bz+dz*mid;
            double mass=1-(ex*ex+.43*ez*ez)/(radius*radius);
            if(mass<=0)continue;
            double half=radius*std::sqrt(mass/aa);
            double low=std::max(.8,mid-half),high=mid+half;
            if(std::abs(dy)>.0001){
                double p=-cy/dy,q=(6.82-cy)/dy;
                low=std::max(low,std::min(p,q));high=std::min(high,std::max(p,q));
            }
            if(high<=low)continue;
            auto integral=[&](double z){double u=std::clamp((z-mid)/half,-1.,1.);return u-u*u*u/3.;};
            // Visibility at the densest part of the shaft, traced back to its lamp.
            double q=std::clamp(mid,low,high);
            V sample{cx+(sx-roll*sy)*q/(1+roll*roll)-bend(cz+q),cy+dy*q,cz+q};
            V ray=V{side*7.8*widthFactor,6.82,fixture}-sample;
            double shade=1;
            double divisor=bankCos*ray.y-bankSin*ray.x;
            if(std::abs(divisor)>.01){
                double syShip=1.95+.18*std::sin(t*pi/2);
                double u=(bankCos*(syShip-sample.y)+bankSin*(sample.x-shipCenter(t)))/divisor;
                if(u>0 && u<1){
                    V at=sample+ray*u;
                    double zz=at.z-(cz+chaseLag+6.4);
                    if(zz>-.91 && zz<2.35)
                        shade*=1-.72*ease(((2.35-zz)*.47-std::abs((at.x-shipCenter(t))/bankCos))/.24);
                }
            }
            if(ray.y>.01 && sample.y<6.75){
                double u=(6.75-sample.y)/ray.y;
                double strike=sample.x+u*ray.x;
                double rib=std::abs(std::remainder(strike-side*7.8*widthFactor,.85));
                shade*=.52+.48*ease((rib-.055)/.13);
            }
            double base=integral(low);
            for(int yy=y;yy<y+2;yy++)for(int xx=x;xx<x+2;xx++){
                int i=yy*W+xx;
                double stop=depths[i]?std::min(high,1./depths[i]):high;
                if(stop<=low)continue;
                double light=(integral(stop)-base)*mass*half*(.17+.085*reveal(13,.30))*reach*shade;
                C color=side>0?C{169,47,118}:C{35,147,156};
                for(int j=0;j<3;j++)rgb[3*i+j]=std::min(255.,rgb[3*i+j]+light*color[j]);
            }
        }
    }
}
void glowOrb(V p,double r,C hot){
    auto v=[&](int i,double scale){double a=i*pi/6;return V{p.x+scale*r*std::cos(a),p.y+scale*r*std::sin(a),p.z};};
    for(int i=0;i<12;i++)tri(p,v(i,1),v(i+1,1),hot);
}
void boltTrails(){
    for(int i=0;i<3;i++){
        double u=(t-cue.bolts[i])/.52;
        if(u<0 || u>1)continue;
        for(int side:{-1,1}){
            auto pos=[&](double f){double bankX=shipCenter(cue.bolts[i]);
                return V{bankX+side*(1.18+.22*f),1.82+2.75*f,route(cue.bolts[i]+.52*f)+6.2+26*f};};
            V head=pos(u),tail=pos(std::max(0.,u-.15));C hot=side<0?C{87,248,255}:C{255,123,205};
            tri(head+V{-.12,0,0},head+V{.12,0,0},tail,hot);
            glowOrb(head,.17,hot);glowOrb(head+V{0,0,-.045},.075,{255,255,238});
        }
    }
}
double shipCenter(double time) const{
    return pilot+2.15*std::sin(time/cue.duration*6*pi)+.65*std::sin(time*pi/4)-3.05*dodge(time);
}
void pulseTarget(){
    if(stage<10 || t<cue.end[9] || t>cue.impact+1.55)return;
    V target{shipCenter(cue.impact)+.35,4.52,route(cue.impact)+18};
    C amber={255,167,61},teal={98,254,246},magenta={251,92,171};
    double age=t-cue.impact;
    if(age<0){
        glowOrb(target,.58+.08*std::sin(t*9),amber);
        for(int j=0;j<6;j++){
            auto v=[&](double a,double r){return target+V{r*std::cos(a),r*std::sin(a),-.09};};
            double a=j*pi/3+t*.72;
            quad(v(a,1.95),v(a+.83,1.95),v(a+.83,1.39),v(a,1.39),j%2?amber:magenta);
            quad(v(a,1.38),v(a+.40,1.38),v(a+.40,1.25),v(a,1.25),{255,232,154});
        }
    }
    double u=(t-cue.launch)/(cue.impact-cue.launch);
    auto pos=[&](double f){
        V barrel{shipCenter(cue.launch)+.99,1.87,route(cue.launch)+6.1};
        V point=barrel+(target-barrel)*(f*(.67+.33*f));
        point.z=route(cue.launch+(cue.impact-cue.launch)*f)+6.1+11.9*f;
        return point+
            V{1.08*std::sin(pi*f),1.28*std::sin(pi*f),0};
    };
    if(u>=0 && u<=1){
        for(int j=15;j>=0;j--){
            double v=u-j*.011;if(v<0)continue;
            double fade=1-j/16.;
            V p=pos(v);p.y+=.10*std::sin(v*37)*j/16.;
            glowOrb(p,.065+.125*(1-fade),mix({74,82,143},amber,fade));
        }
        V p=pos(u);
        V nose=p+V{-.10,.14,.88},engine=p+V{0,0,-.58};
        tri(nose,p+V{-.21,.08,-.32},engine,{222,230,205});
        tri(nose,engine,p+V{.21,.08,-.32},{116,146,171});
        for(int side:{-1,1})tri(p+V{0,.08,.5},p+V{side*.46,-.12,-.65},p+V{0,-.15,-.16},magenta);
        glowOrb(engine,.14,{255,231,135});
    }
    if(age>=0){
        double r=.45+8.4*age;
        for(int j=0;j<40;j++){
            auto arc=[&](int k,double rad){double a=k*pi/20;return target+V{rad*std::cos(a),.78*rad*std::sin(a),-.7+.39*rad*std::sin(a)};};
            if(age<.72)quad(arc(j,r),arc(j+1,r),arc(j+1,r-.18),arc(j,r-.18),age<.18?C{255,242,199}:teal);
            double az=2*pi*random01(j+293),vel=2.8+6*random01(j+371);
            V p=target+V{std::cos(az)*age*vel,std::sin(az)*age*vel-1.8*age*age,-age*(1+random01(j+103)*4)};
            double h=.09+.16*(1-ease(age/1.55));
            tri(p+V{-h,h,0},p+V{h,h*.5,0},p+V{h*std::cos(az+age*4),-h,0},j%3?amber:magenta);
        }
        if(age<.21)glowOrb(target+V{0,0,-.28},1.44*(1-age/.21),{255,245,197});
    }
}
void motionBlur(){
    if(boost<=.002)return;
    const auto source=rgb;
    const Point ahead=project({cx,cy,cz+108});
    const double travel=route(t)-route(t-.017);
    for(int y=0;y<H;y++)for(int x=0;x<W;x++){
        int i=y*W+x;
        double exposure=std::min(.095,travel*depths[i])*boost;
        double dx=(ahead.x-x)*exposure,dy=(ahead.y-y)*exposure;
        double length=std::hypot(dx,dy);
        if(length<1)continue;
        double limit=std::min(1.,(H*.043)/length);
        dx*=limit;dy*=limit;
        int samples=std::clamp(int(std::ceil(length*limit)),3,28);
        int sum[3]={0,0,0};
        for(int k=0;k<samples;k++){
            double u=(k+.5)/samples;
            int xx=std::clamp(int(std::lround(x+dx*u)),0,W-1);
            int yy=std::clamp(int(std::lround(y+dy*u)),0,H-1);
            for(int c=0;c<3;c++)sum[c]+=source[3*(yy*W+xx)+c];
        }
        for(int c=0;c<3;c++)rgb[3*i+c]=(source[3*i+c]+4*sum[c]/samples)/5;
    }
}

// Rival craft enter from opposite shoulders, settle into lanes, then get passed.
std::vector<V> jetLights;
void fleet(bool lightsOnly=false){
    if(!mirror && !casting)jetLights.clear();
    if(stage<13)return;
    double pass=reveal(16,.85),warp=reveal(17,.30);
    int count=stage>=16?5:2;
    for(int j=0;j<count;j++){
        int side=j%2?1:-1;
        double age=t<.72?t+cue.duration:t;
        double arrive=ease((age-cue.end[j<2?12:15]-.09*(j%3))/.72);
        if(arrive<=0)continue;
        double lane=(j<2?2.0:1.10+.5*(j%3))*side;
        double base=11.5+j*3.15;
        double z=base*arrive+4.6-5*(1-arrive)-pass*(16.5-j*1.3);
        if(z<1.5)continue;
        double drift=.43*std::sin(2.4*age+j*2);
        double x=cx+lane*arrive+side*(3.6-1.5*arrive)*(1-arrive)+drift;
        double y=(j==0?3.1:j==1?4.05:2.85+.65*(j-2))+.21*std::sin(2.7*age+j);
        if(!mirror && !casting)jetLights.push_back({x,y-.13,z-1.3});
        if(lightsOnly)continue;
        double lean=-turnBank*.76-.22*std::cos(2.4*age+j*2);
        double cs=std::cos(lean),sn=std::sin(lean);
        auto p=[&](double u,double v,double w){return V{x+1.2*(u*cs-v*sn),y+1.2*(u*sn+v*cs),cz+z+w};};
        const C paints[]={{56,222,165},{215,71,152},{239,177,62},{99,146,248},{165,106,228}};
        C paint=paints[j],light=mix(paint,{227,255,245},.57);
        V nose=p(0,.13,1.6),canopy=p(0,.48,.05),keel=p(0,-.14,-1.03);
        for(int flank:{-1,1}){
            V root=p(flank*.37,.12,.20),tip=p(flank*(j%2?.94:1.15),-.02,-.58),jet=p(flank*.52,.04,-1.13);
            tri(nose,root,canopy,flank<0?C{43,56,75}:C{88,103,122});tri(root,tip,jet,paint);
            tri(root,jet,keel,{43,52,75});tri(root,canopy,keel,{52,65,81});
            tri(tip,p(flank*.93,.46,-.78),jet,light);
            V intake=p(flank*.65,.14,.62),exhaust=p(flank*.65,.24,-.88);
            tri(intake,p(flank*.87,.10,-.75),exhaust,{54,65,89});
            tri(intake,exhaust,p(flank*.50,.10,-.85),paint);
            tri(p(flank*.69,.21,-.33),p(flank*.74,.19,-.46),p(flank*.62,.22,-.46),{246,222,152});
            if(casting)continue;
            tri(p(flank*.52-.10,.08,-1.14),p(flank*.52+.1,.08,-1.14),p(flank*.52,.04,-1.8),{231,255,246});
            double trail=reveal(14,.24);
            if(trail<=0)continue;
            for(int n=0;n<13;n++){
                auto ribbon=[&](int step,double border){
                    double u=step/13.;
                    double wave=.31*u*std::sin(t*5-u*6+j);
                    return p(flank*.52+wave+border*(1-u)*.065,.07-.32*u,-1.19-6*u*trail);
                };
                quad(ribbon(n,-1),ribbon(n,1),ribbon(n+1,1),ribbon(n+1,-1),mix(paint,{48,76,109},.13+.6*n/13.));
            }
        }
        tri(p(-.20,.29,.06),p(.20,.29,.06),p(0,.40,.82),{25,42,63});
    }
    if(casting || lightsOnly || warp<=0 || t<cue.end[17])return;
    // The finish aperture has a fixed world position. Its layers sweep over the camera.
    double z=route(cue.room-.23)+6.4;
    for(int layer=0;layer<5;layer++){
        double zz=z+layer*3.4,rad=5.1+layer*.37;
        for(int k=0;k<32;k++){
            auto v=[&](int n,double r){
                double a=n*2*pi/32+layer*.065;
                return V{1.1+r*std::cos(a),4+r*std::sin(a),zz};
            };
            C tint=layer%2?C{95,243,225}:C{185,114,242};
            quad(v(k,rad),v(k+1,rad),v(k+1,rad-.14),v(k,rad-.14),tint);
