using std::array;
int W=480,H=300;
constexpr double pi=3.141592653589793;
struct V{double x,y,z;};
V operator+(V a,V b){return {a.x+b.x,a.y+b.y,a.z+b.z};}
V operator-(V a,V b){return {a.x-b.x,a.y-b.y,a.z-b.z};}
V operator*(V a,double f){return {a.x*f,a.y*f,a.z*f};}
